    16	};
    17	
    18	pub mod config;
    19	
    20	/// CLI Data Args
    21	#[derive(Args)]
    22	pub struct DataArgs {
    23	    #[command(subcommand)]
    24	    command: DataCommands,
    25	}
    26	
    27	/// CLI Subcommands
    28	#[derive(Subcommand)]
    29	#[allow(missing_docs)]
    30	pub enum DataCommands {
    31	    Members {
    32	        stage: String,
    33	        config: PathBuf,
    34	        #[arg(long)]
    35	        ingestion_key: Option<IngestionKey>,
    36	    },
    37	}
    38	
    39	#[allow(clippy::must_use_candidate, missing_docs)]
    40	impl DataArgs {
    41	    pub fn new_fetch_members(config: PathBuf, ingestion_key: IngestionKey) -> Self {
    42	        Self {
    43	            command: DataCommands::Members {
    44	                config,
    45	                stage: "fetch".to_string(),
    46	                ingestion_key: Some(ingestion_key),
    47	            },
    48	        }
    49	    }
    50	
    51	    pub fn new_load_members(config: PathBuf, ingestion_key: IngestionKey) -> Self {
    52	        Self {
    53	            command: DataCommands::Members {
    54	                config,
    55	                stage: "load".to_string(),
    56	                ingestion_key: Some(ingestion_key),
    57	            },
    58	        }
    59	    }
    60	}
    61	
    62	/// Entry point for CLI commands
    63	///
    64	/// # Errors
    65	/// - Bad stage arg
    66	/// - Bad config path
    67	/// - Bad config shape
    68	/// - Service level failures
    69	pub async fn run_cli(args: DataArgs) -> anyhow::Result<()> {
    70	    match args.command {
    71	        DataCommands::Members {
    72	            stage,
    73	            config,
    74	            ingestion_key,
    75	        } => {
    76	            let stage = MemberIngestionStage::from_str(&stage)?;
    77	            let ingestion_key = ingestion_key.unwrap_or_default();
    78	            match stage {
    79	                MemberIngestionStage::Fetch => {
    80	                    let config = FetcherConfig::try_from(&config)?;
    81	                    let api = ParliamentApiClient::new(config.batch_size)?;
    82	                    let fs = ExposedDataPipeline::new_with_ingestion_key(
    83	                        &config.data_dir,
    84	                        ingestion_key,
    85	                    )?;
    86	                    let service = FetcherService::new(fs, api);
    87	
    88	                    let req = EntityIngestionRequest {};
    89	                    service.fetch_members(&req).await?;
    90	                }
    91	                MemberIngestionStage::Load => {
    92	                    let config = LoaderConfig::try_from(&config)?;
    93	                    let fs = ExposedDataPipeline::new_with_ingestion_key(
    94	                        &config.data_dir,
    95	                        ingestion_key,
    96	                    )?;
    97	                    let db = ExposedDatabase::new(&config.connection_string).await;
    98	                    let service = IngesterService::new(fs, db);
    99	
   100	                    service.load_members().await?;
   101	                }
   102	            }
   103	        }
   104	    }
   105	    Ok(())
   106	}
