 28	
 29	    match response.status() {
 30	        StatusCode::OK => {
 31	            let bytes = response.bytes().await?;
 32	            let data: Value = serde_json::from_slice(&bytes)?;
 33	            let entities = data
 34	                .get("entities")
 35	                .and_then(|d| d.as_array())
 36	                .ok_or(anyhow::anyhow!("unparsable"))?
 37	                .to_vec();
 38	            Ok(entities)
 39	        }
 40	        StatusCode::INTERNAL_SERVER_ERROR => Err(anyhow::anyhow!("something unexpected happened")),
