    18	/// Allows users to search the databse using free text.
    19	#[derive(Clone)]
    20	pub struct FetcherService<PS, PA> {
    21	    pipeline_storage: PS,
    22	    parliament_api: PA,
    23	}
    24	
    25	impl<PS, PA> FetcherService<PS, PA> {
    26	    /// Creates a new instance
    27	    pub const fn new(pipeline_storage: PS, parliament_api: PA) -> Self {
    28	        Self {
    29	            pipeline_storage,
    30	            parliament_api,
    31	        }
    32	    }
    33	}
    34	
    35	impl<PS, PA> EntityFetcherService for FetcherService<PS, PA>
    36	where
    37	    PS: EntityIngestionStorage,
    38	    PA: ParliamentApi,
    39	{
    40	    async fn fetch_members(
    41	        &self,
    42	        _req: &EntityIngestionRequest,
