L39: ### cite5†§ Quick Start
L40: 
L41: You can create an application declaratively with a `struct` and some attributes.
L42: 
L43: First, ensure `clap` is available with the cite23†`derive` feature flag :
L44: 
L45:     `$ cargo add clap --features derive`
L46: Here is a preview of the type of application you can make:
L47: 
L48:     `use std::path::PathBuf;
L49: 
L50:     use clap::{Parser, Subcommand};
L51: 
L52:     #[derive(Parser)]
L53:     #[command(version, about, long_about = None)]
L54:     struct Cli {
L55:         /// Optional name to operate on
L56:         name: Option<String>,
L57: 
L58:         /// Sets a custom config file
L59:         #[arg(short, long, value_name = "FILE")]
L60:         config: Option<PathBuf>,
L61: 
L62:         /// Turn debugging information on
L63:         #[arg(short, long, action = clap::ArgAction::Count)]
L64:         debug: u8,
L65: 
L66:         #[command(subcommand)]
L67:         command: Option<Commands>,
L68:     }
L69: 
L70:     #[derive(Subcommand)]
L71:     enum Commands {
L72:         /// does testing things
L73:         Test {
L74:             /// lists test values
L75:             #[arg(short, long)]
L76:             list: bool,
L77:         },
L78:     }
L79: 
L80:     fn main() {
L81:         let cli = Cli::parse();
L82: 
L83:         // You can check the value provided by positional arguments, or option arguments
L84:         if let Some(name) = cli.name.as_deref() {
L85:             println!("Value for name: {name}");
L86:         }
L87: 
L88:         if let Some(config_path) = cli.config.as_deref() {
L89:             println!("Value for config: {}", config_path.display());
L90:         }
L91: 
L92:         // You can see how many times a particular flag or argument occurred
L93:         // Note, only flags can have multiple occurrences
L94:         match cli.debug {
L95:             0 => println!("Debug mode is off"),
L96:             1 => println!("Debug mode is kind of on"),
L97:             2 => println!("Debug mode is on"),
L98:             _ => println!("Don't be crazy"),
L99:         }
L100: 
L101:         // You can check for the existence of subcommands, and if found use their
L102:         // matches just as you would the top level cmd
L103:         match &cli.command {
L104:             Some(Commands::Test { list }) => {
L105:                 if *list {
L106:                     println!("Printing testing lists...");
L107:                 } else {
L108:                     println!("Not printing testing lists...");
L109:                 }
L110:             }
L111:             None => {}
L112:         }
L113: 
L114:         // Continued program logic goes here...
L115:     }`
