    24	#[tokio::test]
    25	async fn shows_no_hsbc_duplicates() {
    26	    let _guard = start_app().await.unwrap();
    27	    time::sleep(Duration::from_secs(2)).await;
    28	
    29	    let known_duplicate = EntitySearchRequest::new_with_strictness("HSBC".into(), 10, 0.9).unwrap();
    30	    let entities = search_entities(&known_duplicate).await.unwrap();
    31	
    32	    let mut duplicates: HashMap<String, usize> = HashMap::new();
    33	    for e in entities.into_iter() {
    34	        duplicates
    35	            .entry(e.get("name").unwrap().as_str().unwrap().into())
    36	            .and_modify(|count| *count += 1)
    37	            .or_insert(1);
    38	    }
    39	
    40	    assert_eq!(duplicates.get("HSBC UK Bank plc"), Some(&1));
    41	    assert_eq!(duplicates.get("HSBC UK Bank PLC"), Some(&1));
    42	    assert_eq!(duplicates.get("HSBC UK (Ian Stuart, CEO)"), Some(&1));
    43	}
    44	
    45	#[sqlx::test(migrations = "../db/migrations")]
    46	async fn parliament_api_parses_all_sitting_members(pool: PgPool) -> sqlx::Result<()> {
    47	    let ingestion_key = IngestionKey::default();
    48	    let tmp = TempDir::new().unwrap();
    49	
    50	    let (_file, path) = cli_fetcher_config(&tmp);
    51	    let args = DataArgs::new_fetch_members(path, ingestion_key.clone());
    52	    run_cli(args).await.unwrap();
    53	
    54	    let url = pool.connect_options().to_url_lossy();
    55	    let (_file, path) = cli_loader_config(&tmp, url.to_string().as_str());
    56	    let args = DataArgs::new_load_members(path, ingestion_key.clone());
    57	    run_cli(args).await.unwrap();
    58	
    59	    let db = ExposedDatabase::from(pool);
    60	
    61	    let params =
    62	        EntitySearchRequest::new_with_strictness("John McDonnell".into(), 10, 0.8).unwrap();
    63	    let res = db.get_members_by_text_search_score(&params).await.unwrap();
    64	
    65	    let (mp, _) = res.first().unwrap();
    66	    assert_eq!(mp.name(), "John McDonnell".to_string());
    67	
    68	    Ok(())
